"""What every target generator provides."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from ..messages import Msg
from ..model.theme import Theme

# First line of every generated file. A file at a planned path that does not
# start with it was not written by this app and is reported before it is replaced.
MARKER = "# Generated by Plasma Theme Studio."
# The same for files that cannot start with a "#" line. A generated SVG file
# starts with XML_MARKER (and has no XML declaration); a generated JSON file
# starts with JSON_MARKER, which is its first key.
XML_MARKER = "<!-- Generated by Plasma Theme Studio. -->"
JSON_MARKER = '{\n  "X-Generated-By": "Plasma Theme Studio",'
MARKERS = (MARKER, XML_MARKER, JSON_MARKER)


def made_here(path: Path) -> bool:
    """Whether the file at `path` was written by this app."""
    try:
        with path.open(encoding="utf-8") as stream:
            return stream.read(200).startswith(MARKERS)
    except (OSError, UnicodeDecodeError):
        return False


class ApplyError(Exception):
    """`restored` is False when a failed apply could not be rolled back completely."""

    def __init__(self, message: Msg, restored: bool = True):
        self.message = message
        self.restored = restored
        super().__init__(str(message))


@dataclass(frozen=True)
class PlannedFile:
    path: Path
    content: str
    # What the content starts with, so that the file is recognized later.
    marker: str = MARKER


class Generator:
    """One target of a theme, for example the Plasma color scheme."""

    id: str = ""
    title: Msg
    # The theme sections this target reads. The UI shows the target's notes there.
    sections: tuple[str, ...] = ()

    def wanted(self, theme: Theme) -> bool:
        """Whether the theme asks for this target at all. A target that is not
        wanted is left alone: nothing is written, captured, reloaded or checked."""
        return True

    def notes(self, theme: Theme) -> list[Msg]:
        """What the user should know about how the theme's values end up on the
        desktop: values this target cannot apply exactly, or that it is turned
        off. Needs no access to the system and is shown while editing."""
        return []

    def section_notes(self, theme: Theme, section: str) -> list[Msg]:
        """The notes that belong on the page of one section. A target that
        reads several sections says on each page only what concerns it."""
        return self.notes(theme)

    def stale_files(self, theme: Theme) -> list[Path]:
        """Files and folders this target wrote earlier and no longer needs once
        `theme` is applied. They are kept in the snapshot and removed after a
        successful reload. Only return what `made_here` recognizes."""
        return []

    def unavailable_reason(self, runner) -> Msg | None:
        """Why this target cannot be applied on this system, or None if it can."""
        return None

    def files(self, theme: Theme) -> list[PlannedFile]:
        raise NotImplementedError

    def check_output(self, file: PlannedFile) -> list[Msg]:
        """Problems with generated content. Anything returned blocks the apply."""
        return []

    def problems(self, theme: Theme) -> list[Msg]:
        """Reasons this theme cannot be applied to this target."""
        return []

    def warnings(self, theme: Theme, runner) -> list[Msg]:
        return []

    def is_active(self, theme: Theme, runner) -> bool:
        """Whether the desktop is currently using this theme's output for this target."""
        return False

    def reload_command(self, theme: Theme) -> str:
        """The command shown to the user as the way this target is reloaded."""
        return ""

    def changed_settings(self, theme: Theme) -> list[Msg]:
        """The settings this target changes besides writing its files and running
        its reload command, in words. Shown to the user before an apply."""
        return []

    def capture_settings(self, runner) -> dict:
        """Desktop settings to store in a snapshot before applying."""
        return {}

    def reload(self, theme: Theme, runner) -> None:
        """Make the desktop use the files that were just written."""

    def restore_settings(self, settings: dict, runner) -> None:
        """Put back the settings stored by `capture_settings`."""
